/**
 * Shared <ViewTransition> configuration.
 *
 * Kept in one module so the grid and the detail page can never drift apart on
 * the names and classes they animate with — a shared element only morphs when
 * both sides agree on `name`.
 */

/**
 * Directional slides are opt-in per navigation, via `<Link transitionTypes>`.
 * Transitions that carry no type (browser back/forward, router.refresh(),
 * Suspense reveals) fall through to `none` so they never slide sideways.
 */
const directional = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
}

/**
 * Wraps the root element of each `page.tsx`. It has to live in the page rather
 * than the layout: layouts persist across navigations, so enter/exit would
 * never fire there.
 */
export const pageSlide = {
  enter: directional,
  exit: directional,
  default: 'none',
}

/**
 * The grid thumbnail and the detail hero share this name, so React pairs them
 * and animates one into the other instead of crossfading two unrelated boxes.
 * `default: 'none'` keeps the image from animating on its own during unrelated
 * transitions; `share` still has to be explicit for the pair to morph.
 */
export function productImage(slug: string) {
  return {
    name: `product-${slug}`,
    share: 'morph',
    default: 'none',
  }
}

/**
 * Suspense fallback → content handoff: the skeleton slides down and out, the
 * content slides up and in.
 *
 * Both are scoped to untyped transitions. During a directional navigation the
 * skeleton and the content should travel with the page slide as part of its
 * snapshot, not break away and animate on their own axis.
 */
export const skeletonReveal = {
  exit: { 'nav-forward': 'none', 'nav-back': 'none', default: 'slide-down' },
  default: 'none',
}

export const contentReveal = {
  enter: { 'nav-forward': 'none', 'nav-back': 'none', default: 'slide-up' },
  default: 'none',
}

