@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ==========================================================================
   View transitions

   Classes here are assigned by the `share` / `enter` / `exit` props on the
   <ViewTransition> components in app/view-transitions.ts. The old content
   leaves quickly so it stops competing for attention; the new content arrives
   more gently, and waits for the exit to finish before it becomes visible.
   ========================================================================== */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* The transition overlay swallows pointer events by default, so clicks made
   mid-animation are lost. Let them through to the live page underneath. */
::view-transition {
  pointer-events: none;
}

/* --- Shared element: grid thumbnail <-> detail hero ---------------------- */

::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}

/* A touch of blur mid-flight hides the pixel interpolation between two
   differently sized snapshots. */
::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}

@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* --- Suspense reveal: skeleton hands off to content --------------------- */

::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}

::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

/* --- Directional navigation --------------------------------------------- */

/* Forward: the old page leaves to the left, the new one arrives from the
   right. Back reverses both. 60px is enough to read as direction without
   making the eye chase content across the viewport. */
::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}

::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}

::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

@keyframes slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

/* --- Reduced motion ----------------------------------------------------- */

/* Sideways slides simulate physical movement across the viewport, the most
   common trigger for motion sensitivity. Zeroing the durations drops every
   transition back to the browser's default instant swap; navigation, the
   morph and the Suspense reveals all still work, they just don't animate. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation-duration: 0s !important;
    animation-delay: 0s !important;
  }

  /* The skeletons' looping pulse is motion too. */
  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

